def semver_sort(versions):
    def parse(v):
        # split build metadata
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None
        major, minor, patch = (int(x) for x in main.split('.'))
        if pre is None:
            pre_ids = None
        else:
            ids = pre.split('.')
            pre_ids = tuple(
                (0, int(i)) if i.isdigit() else (1, i)
                for i in ids
            )
        return (major, minor, patch, pre_ids)

    def key(v):
        major, minor, patch, pre_ids = parse(v)
        has_pre = pre_ids is not None
        # versions with prerelease come before those without
        return (major, minor, patch, 0 if has_pre else 1, pre_ids if has_pre else ())

    return sorted(versions, key=key)

